pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public {
        c = new ModifierEntrancy();
    }

    function testFuzz_property(uint256 amount) public {
        // Amount is unused by the contract's observable state delta (fixed +20),
        // but it is a fuzzed input that keeps the domain wide and lets the
        // fuzzer explore arbitrary starting balances absent/zero cases.
        amount;

        Bank b = new Bank();
        address actor = address(b);

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.airDrop();

        assertTrue(c.tokenBalance(actor) == 20);
    }
}
